--- a/Documents/kyoto-planner/style.css
+++ b/Documents/kyoto-planner/style.css
@@ -0,0 +1,274 @@
+/* Kyoto in Autumn — print stylesheet (A4) */
+@page {
+  size: A4;
+  margin: 14mm 13mm 16mm 13mm;
+}
+
+:root {
+  --ink:      #16202e;
+  --ink-soft: #46536a;
+  --muted:    #7b8798;
+  --rule:     #dcd8d0;
+  --paper:    #ffffff;
+  --wash:     #f7f5f1;
+  --maple:    #a8342a;
+  --maple-lt: #f4e7e4;
+  --moss:     #3f6b4f;
+  --moss-lt:  #e8efe9;
+  --gold:     #9a7526;
+  --indigo:   #1d2c47;
+}
+
+* { box-sizing: border-box; }
+
+html { font-size: 10pt; }
+
+body {
+  margin: 0;
+  font-family: "Inter", "DejaVu Sans", sans-serif;
+  color: var(--ink);
+  background: var(--paper);
+  line-height: 1.45;
+  -webkit-font-smoothing: antialiased;
+}
+
+a { color: var(--maple); text-decoration: none; }
+
+/* ---------- cover ---------- */
+.cover {
+  height: 262mm;
+  display: flex;
+  flex-direction: column;
+  justify-content: space-between;
+  page-break-after: always;
+}
+.cover-top { padding-top: 16mm; }
+.kicker {
+  font-size: 8.5pt;
+  letter-spacing: .22em;
+  text-transform: uppercase;
+  color: var(--maple);
+  font-weight: 600;
+}
+.cover h1 {
+  font-family: "Inter Display", "Inter", sans-serif;
+  font-size: 46pt;
+  line-height: 1.02;
+  letter-spacing: -.02em;
+  margin: 6mm 0 0 0;
+  color: var(--indigo);
+}
+.cover h1 em { font-style: normal; color: var(--maple); }
+.cover .sub {
+  font-size: 13pt;
+  color: var(--ink-soft);
+  margin-top: 6mm;
+  max-width: 128mm;
+  line-height: 1.5;
+}
+.cover-rule {
+  height: 3px;
+  background: linear-gradient(90deg, var(--maple) 0 34mm, var(--gold) 34mm 48mm, var(--rule) 48mm 100%);
+  margin: 9mm 0;
+}
+.cover-facts {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 6mm;
+  padding: 6mm 0 0 0;
+  border-top: 1px solid var(--rule);
+}
+.cover-facts .n {
+  font-family: "Inter Display", sans-serif;
+  font-size: 20pt;
+  color: var(--indigo);
+  letter-spacing: -.01em;
+}
+.cover-facts .l {
+  font-size: 8pt;
+  text-transform: uppercase;
+  letter-spacing: .12em;
+  color: var(--muted);
+  margin-top: 1.5mm;
+}
+.cover-foot {
+  font-size: 8.5pt;
+  color: var(--muted);
+  border-top: 1px solid var(--rule);
+  padding-top: 4mm;
+}
+.cover-foot strong { color: var(--ink-soft); }
+
+/* ---------- generic blocks ---------- */
+h2 {
+  font-family: "Inter Display", "Inter", sans-serif;
+  font-size: 17pt;
+  letter-spacing: -.01em;
+  margin: 0 0 1mm 0;
+  color: var(--indigo);
+}
+h3 {
+  font-size: 10.5pt;
+  margin: 6mm 0 2mm 0;
+  color: var(--indigo);
+}
+.lede { font-size: 10pt; color: var(--ink-soft); margin: 0 0 4mm 0; }
+
+.section-head {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  border-bottom: 2px solid var(--ink);
+  padding-bottom: 2mm;
+  margin-bottom: 4mm;
+}
+.section-head .tag {
+  font-size: 8pt;
+  letter-spacing: .16em;
+  text-transform: uppercase;
+  color: var(--muted);
+}
+
+.page-break { page-break-before: always; }
+.avoid-break { page-break-inside: avoid; }
+
+p { margin: 0 0 3mm 0; }
+ul { margin: 0 0 3mm 0; padding-left: 5mm; }
+li { margin-bottom: 1.2mm; }
+
+/* ---------- day cards ---------- */
+.day-head {
+  display: flex;
+  justify-content: space-between;
+  align-items: flex-end;
+  border-bottom: 2px solid var(--maple);
+  padding-bottom: 2mm;
+  margin-bottom: 3mm;
+}
+.day-head .n {
+  font-family: "Inter Display", sans-serif;
+  font-size: 9pt;
+  letter-spacing: .2em;
+  text-transform: uppercase;
+  color: var(--maple);
+}
+.day-head h2 { margin-top: 1mm; }
+.day-head .meta { text-align: right; font-size: 8.5pt; color: var(--muted); }
+.day-head .meta b { color: var(--ink); font-weight: 600; }
+
+.strip {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 4mm;
+  background: var(--wash);
+  border-left: 3px solid var(--gold);
+  padding: 3mm 4mm;
+  margin-bottom: 4mm;
+}
+.strip .k { font-size: 7.5pt; text-transform: uppercase; letter-spacing: .1em; color: var(--muted); }
+.strip .v { font-size: 10pt; font-weight: 600; color: var(--indigo); }
+
+/* ---------- stop table ---------- */
+table.stops {
+  width: 100%;
+  border-collapse: collapse;
+  margin-bottom: 4mm;
+}
+table.stops thead th {
+  font-size: 7.5pt;
+  text-transform: uppercase;
+  letter-spacing: .1em;
+  color: var(--muted);
+  text-align: left;
+  border-bottom: 1px solid var(--rule);
+  padding: 0 2mm 1.5mm 0;
+  font-weight: 600;
+}
+table.stops td {
+  vertical-align: top;
+  padding: 2.2mm 2mm 2.2mm 0;
+  border-bottom: 1px solid var(--rule);
+  font-size: 9pt;
+}
+table.stops tr.tall td { background: var(--wash); }
+td.time { width: 15mm; color: var(--ink-soft); font-variant-numeric: tabular-nums; white-space: nowrap; }
+td.stop { width: auto; }
+td.stop .nm { font-weight: 600; color: var(--indigo); }
+td.stop .why { display: block; color: var(--ink-soft); font-size: 8.5pt; margin-top: .6mm; }
+td.stop .geo { display: block; color: var(--muted); font-size: 7.5pt; font-family: "JetBrains Mono", monospace; margin-top: .6mm; }
+td.fee { width: 46mm; font-size: 8.5pt; color: var(--ink-soft); }
+td.fee b { color: var(--ink); font-weight: 600; }
+td.map { width: 16mm; text-align: right; white-space: nowrap; }
+td.map a {
+  font-size: 8pt;
+  font-weight: 600;
+  border: 1px solid var(--maple);
+  border-radius: 3px;
+  padding: .8mm 1.6mm;
+  color: var(--maple);
+}
+.meal td { background: var(--moss-lt); }
+.meal .nm { color: var(--moss); }
+
+/* ---------- budget ---------- */
+table.money {
+  width: 100%;
+  border-collapse: collapse;
+  font-size: 9pt;
+  margin-bottom: 4mm;
+}
+table.money th {
+  text-align: left;
+  font-size: 7.5pt;
+  text-transform: uppercase;
+  letter-spacing: .1em;
+  color: var(--muted);
+  border-bottom: 1px solid var(--rule);
+  padding: 0 2mm 1.5mm 0;
+}
+table.money td {
+  padding: 2mm 2mm 2mm 0;
+  border-bottom: 1px solid var(--rule);
+  vertical-align: top;
+}
+table.money td.num, table.money th.num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
+table.money tr.total td {
+  border-top: 1.5px solid var(--ink);
+  border-bottom: none;
+  font-weight: 700;
+  color: var(--indigo);
+  font-size: 10pt;
+  padding-top: 2.5mm;
+}
+table.money tr.sub td { background: var(--wash); font-weight: 600; color: var(--indigo); }
+
+/* ---------- cards (rainy day) ---------- */
+.card {
+  border: 1px solid var(--rule);
+  border-top: 3px solid var(--indigo);
+  padding: 4mm;
+  margin-bottom: 4mm;
+  page-break-inside: avoid;
+}
+.card h3 { margin-top: 0; }
+.card .where { font-size: 8pt; text-transform: uppercase; letter-spacing: .1em; color: var(--muted); margin-bottom: 2mm; }
+.card p { font-size: 9pt; margin-bottom: 2mm; }
+.card .cost { font-size: 9pt; font-weight: 600; color: var(--moss); }
+
+.note {
+  border-left: 3px solid var(--moss);
+  background: var(--moss-lt);
+  padding: 3mm 4mm;
+  font-size: 8.5pt;
+  color: var(--ink-soft);
+  margin-bottom: 4mm;
+}
+.note b { color: var(--ink); }
+
+.tiles { display: grid; grid-template-columns: 1fr 1fr; gap: 4mm; }
+
+/* ---------- sources ---------- */
+ol.sources { font-size: 8pt; color: var(--ink-soft); padding-left: 6mm; }
+ol.sources li { margin-bottom: 1.6mm; }
+ol.sources .t { color: var(--ink); }
+ol.sources .u { font-family: "JetBrains Mono", monospace; font-size: 7pt; color: var(--muted); word-break: break-all; }
